#include <stddef.h>
#include <stdint.h>

typedef struct arena {
    void *buf;
    size_t size;
    void *next;
    size_t used;
} arena_t;

// Initialize the allocator with a buffer and reset all state
void arena_init(void *buf, size_t size) {
    arena_t *a = (arena_t *)buf;
    a->buf = buf;
    a->size = size;
    a->next = a->buf;
    a->used = 0;
}

